from collections import Counter
mask={(r,c) for r in range(7) for c in range(20) if grid[13+r][c]==1}
shapes=Counter({(4,2):1,(2,2):2,(2,1):4,(6,2):1,(4,3):1,(3,2):2,(3,1):1,(1,1):3})
# list candidate placements per shape
placements=[]
for (h,w),n in shapes.items():
    for r in range(7-h+1):
        for c in range(20-w+1):
            cells=frozenset((rr,cc) for rr in range(r,r+h) for cc in range(c,c+w))
            if cells<=mask:
                placements.append(((h,w),r,c,cells))
len(mask), len(placements), Counter((x[0] for x in placements))

# Exact-cover recursion, tiles retain identities only by dimensions
from functools import lru_cache
shape_keys=list(shapes)
by_origin={}
for sh,r,c,cells in placements:
    by_origin.setdefault((r,c),[]).append((sh,cells))
@lru_cache(None)
def solve(covered_frozen, counts_tuple):
    covered=set(covered_frozen)
    if len(covered)==len(mask): return ((),) if not any(counts_tuple) else ()
    # choose earliest uncovered cell
    r,c=min(mask-covered)
    sols=[]
    for sh,cells in by_origin.get((r,c),[]):
        idx=shape_keys.index(sh)
        if counts_tuple[idx]<=0 or not cells.isdisjoint(covered): continue
        newcounts=list(counts_tuple);newcounts[idx]-=1
        tails=solve(frozenset(covered|set(cells)),tuple(newcounts))
        for tail in tails:
            sols.append((((sh,r,c),)+tail))
    return tuple(sols)
sols=solve(frozenset(),tuple(shapes[k] for k in shape_keys))
len(sols), solve.cache_info(), shape_keys
